export const templates = {"attendance":"<!doctype html>\n<html lang=\"en\">\n  {{> head}}\n  <body class=\"antialiased\">\n    {{> sidebar}}\n    <div class=\"sidebar-backdrop\" data-sidebar-close></div>\n    <div class=\"workspace\">\n      {{> headerBar}}\n      <main class=\"container\" id=\"main-content\" tabindex=\"-1\">\n        {{> messages}}\n        {{> pages/attendance}}\n      </main>\n      {{> footer}}\n    </div>\n    {{> scripts}}\n  </body>\n</html>\n","connections":"<!doctype html>\n<html lang=\"en\">\n  {{> head}}\n  <body class=\"antialiased\">\n    {{> sidebar}}\n    <div class=\"sidebar-backdrop\" data-sidebar-close></div>\n    <div class=\"workspace\">\n      {{> headerBar}}\n      <main class=\"container\" id=\"main-content\" tabindex=\"-1\">\n        {{> messages}}\n        {{> pages/connections}}\n      </main>\n      {{> footer}}\n    </div>\n    {{> scripts}}\n  </body>\n</html>\n","dashboard":"<!doctype html>\n<html lang=\"en\">\n  {{> head}}\n  <body class=\"antialiased\">\n    {{> sidebar}}\n    <div class=\"sidebar-backdrop\" data-sidebar-close></div>\n    <div class=\"workspace\">\n      {{> headerBar}}\n      <main class=\"container\" id=\"main-content\" tabindex=\"-1\">\n        {{> messages}}\n        {{> pages/dashboard}}\n      </main>\n      {{> footer}}\n    </div>\n    {{> scripts}}\n  </body>\n</html>\n","departments":"<!doctype html>\n<html lang=\"en\">\n  {{> head}}\n  <body class=\"antialiased\">\n    {{> sidebar}}\n    <div class=\"sidebar-backdrop\" data-sidebar-close></div>\n    <div class=\"workspace\">\n      {{> headerBar}}\n      <main class=\"container\" id=\"main-content\" tabindex=\"-1\">\n        {{> messages}}\n        {{> pages/departments}}\n      </main>\n      {{> footer}}\n    </div>\n    {{> scripts}}\n  </body>\n</html>\n","employee-form":"<!doctype html>\n<html lang=\"en\">\n  {{> head}}\n  <body class=\"antialiased\">\n    {{> sidebar}}\n    <div class=\"sidebar-backdrop\" data-sidebar-close></div>\n    <div class=\"workspace\">\n      {{> headerBar}}\n      <main class=\"container\" id=\"main-content\" tabindex=\"-1\">\n        {{> messages}}\n        {{> pages/employee-form}}\n      </main>\n      {{> footer}}\n    </div>\n    {{> scripts}}\n  </body>\n</html>\n","employees":"<!doctype html>\n<html lang=\"en\">\n  {{> head}}\n  <body class=\"antialiased\">\n    {{> sidebar}}\n    <div class=\"sidebar-backdrop\" data-sidebar-close></div>\n    <div class=\"workspace\">\n      {{> headerBar}}\n      <main class=\"container\" id=\"main-content\" tabindex=\"-1\">\n        {{> messages}}\n        {{> pages/employees}}\n      </main>\n      {{> footer}}\n    </div>\n    {{> scripts}}\n  </body>\n</html>\n","error":"<!doctype html>\n<html lang=\"en\">\n  {{> head}}\n  <body class=\"antialiased\">\n    {{> pages/error}}\n    {{> scripts}}\n  </body>\n</html>\n","leaves":"<!doctype html>\n<html lang=\"en\">\n  {{> head}}\n  <body class=\"antialiased\">\n    {{> sidebar}}\n    <div class=\"sidebar-backdrop\" data-sidebar-close></div>\n    <div class=\"workspace\">\n      {{> headerBar}}\n      <main class=\"container\" id=\"main-content\" tabindex=\"-1\">\n        {{> messages}}\n        {{> pages/leaves}}\n      </main>\n      {{> footer}}\n    </div>\n    {{> scripts}}\n  </body>\n</html>\n","login":"<!doctype html>\n<html lang=\"en\">\n  {{> head}}\n  <body class=\"antialiased\">\n    {{> pages/login}}\n    {{> scripts}}\n  </body>\n</html>\n","payroll-detail":"<!doctype html>\n<html lang=\"en\">\n  {{> head}}\n  <body class=\"antialiased\">\n    {{> sidebar}}\n    <div class=\"sidebar-backdrop\" data-sidebar-close></div>\n    <div class=\"workspace\">\n      {{> headerBar}}\n      <main class=\"container\" id=\"main-content\" tabindex=\"-1\">\n        {{> messages}}\n        {{> pages/payroll-detail}}\n      </main>\n      {{> footer}}\n    </div>\n    {{> scripts}}\n  </body>\n</html>\n","payroll":"<!doctype html>\n<html lang=\"en\">\n  {{> head}}\n  <body class=\"antialiased\">\n    {{> sidebar}}\n    <div class=\"sidebar-backdrop\" data-sidebar-close></div>\n    <div class=\"workspace\">\n      {{> headerBar}}\n      <main class=\"container\" id=\"main-content\" tabindex=\"-1\">\n        {{> messages}}\n        {{> pages/payroll}}\n      </main>\n      {{> footer}}\n    </div>\n    {{> scripts}}\n  </body>\n</html>\n","payslip":"<!doctype html>\n<html lang=\"en\">\n  {{> head}}\n  <body class=\"antialiased\">\n    {{> sidebar}}\n    <div class=\"sidebar-backdrop\" data-sidebar-close></div>\n    <div class=\"workspace\">\n      {{> headerBar}}\n      <main class=\"container\" id=\"main-content\" tabindex=\"-1\">\n        {{> messages}}\n        {{> pages/payslip}}\n      </main>\n      {{> footer}}\n    </div>\n    {{> scripts}}\n  </body>\n</html>\n","payslips":"<!doctype html>\n<html lang=\"en\">\n  {{> head}}\n  <body class=\"antialiased\">\n    {{> sidebar}}\n    <div class=\"sidebar-backdrop\" data-sidebar-close></div>\n    <div class=\"workspace\">\n      {{> headerBar}}\n      <main class=\"container\" id=\"main-content\" tabindex=\"-1\">\n        {{> messages}}\n        {{> pages/payslips}}\n      </main>\n      {{> footer}}\n    </div>\n    {{> scripts}}\n  </body>\n</html>\n","profile":"<!doctype html>\n<html lang=\"en\">\n  {{> head}}\n  <body class=\"antialiased\">\n    {{> sidebar}}\n    <div class=\"sidebar-backdrop\" data-sidebar-close></div>\n    <div class=\"workspace\">\n      {{> headerBar}}\n      <main class=\"container\" id=\"main-content\" tabindex=\"-1\">\n        {{> messages}}\n        {{> pages/profile}}\n      </main>\n      {{> footer}}\n    </div>\n    {{> scripts}}\n  </body>\n</html>\n","reports":"<!doctype html>\n<html lang=\"en\">\n  {{> head}}\n  <body class=\"antialiased\">\n    {{> sidebar}}\n    <div class=\"sidebar-backdrop\" data-sidebar-close></div>\n    <div class=\"workspace\">\n      {{> headerBar}}\n      <main class=\"container\" id=\"main-content\" tabindex=\"-1\">\n        {{> messages}}\n        {{> pages/reports}}\n      </main>\n      {{> footer}}\n    </div>\n    {{> scripts}}\n  </body>\n</html>\n","settings":"<!doctype html>\n<html lang=\"en\">\n  {{> head}}\n  <body class=\"antialiased\">\n    {{> sidebar}}\n    <div class=\"sidebar-backdrop\" data-sidebar-close></div>\n    <div class=\"workspace\">\n      {{> headerBar}}\n      <main class=\"container\" id=\"main-content\" tabindex=\"-1\">\n        {{> messages}}\n        {{> pages/settings}}\n      </main>\n      {{> footer}}\n    </div>\n    {{> scripts}}\n  </body>\n</html>\n","users":"<!doctype html>\n<html lang=\"en\">\n  {{> head}}\n  <body class=\"antialiased\">\n    {{> sidebar}}\n    <div class=\"sidebar-backdrop\" data-sidebar-close></div>\n    <div class=\"workspace\">\n      {{> headerBar}}\n      <main class=\"container\" id=\"main-content\" tabindex=\"-1\">\n        {{> messages}}\n        {{> pages/users}}\n      </main>\n      {{> footer}}\n    </div>\n    {{> scripts}}\n  </body>\n</html>\n"};
export const partials = {"footer":"<footer class=\"site-footer\">MindaFresh Food Distribution, Inc. · PeoplePay · Shared ERP database</footer>\n","forms/attendanceFilter":"<form method=\"get\" action=\"/attendance\" class=\"attendance-filter\"><label>From<input type=\"date\" name=\"start\" value=\"{{start}}\" required></label><label>Through<input type=\"date\" name=\"end\" value=\"{{end}}\" required></label><label>Employee<select name=\"employee_id\"><option value=\"\">All employees</option>{{#each employeesForFilter}}<option value=\"{{id}}\" {{#if selected}}selected{{/if}}>{{employee_code}} · {{full_name}}</option>{{/each}}</select></label><button class=\"btn primary\" type=\"submit\">Apply filters</button><button class=\"btn\" type=\"button\" data-print>Print DTR</button></form>\n","forms/employeeForm":"<form method=\"post\" action=\"{{formAction}}\" class=\"form-content\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{csrf}}\" /><input\n      type=\"hidden\"\n      name=\"return_to\"\n      value=\"/employees\"\n    />\n    <div class=\"form-grid\">\n      <label\n        >First name<input\n          type=\"text\"\n          name=\"first_name\"\n          value=\"{{employee.first_name}}\"\n          required\n          maxlength=\"50\" /></label\n      ><label\n        >Last name<input\n          type=\"text\"\n          name=\"last_name\"\n          value=\"{{employee.last_name}}\"\n          required\n          maxlength=\"50\" /></label\n      ><label\n        >Middle name<input\n          type=\"text\"\n          name=\"middle_name\"\n          value=\"{{employee.middle_name}}\"\n          maxlength=\"50\" /></label\n      ><label\n        >Birth date<input\n          type=\"date\"\n          name=\"birth_date\"\n          value=\"{{employee.birth_date}}\" /></label\n      ><label\n        >Email<input\n          type=\"email\"\n          name=\"email\"\n          value=\"{{employee.email}}\"\n          maxlength=\"100\" /></label\n      ><label\n        >Phone<input\n          type=\"tel\"\n          name=\"phone\"\n          value=\"{{employee.phone}}\"\n          maxlength=\"20\" /></label\n      ><label\n        >Address<input\n          type=\"text\"\n          name=\"address\"\n          value=\"{{employee.address}}\"\n          maxlength=\"255\"\n      /></label>\n      <label\n        >Department<select name=\"department_id\" required>\n          {{#each departments}}\n          <option value=\"{{id}}\" {{selected id @root.employee.department_id}}>{{name}}</option>\n          {{/each}}\n        </select></label\n      >\n      <label\n        >Position<input\n          type=\"text\"\n          name=\"position\"\n          value=\"{{employee.position}}\"\n          required\n          maxlength=\"100\" /></label\n      ><label\n        >Employment type<select name=\"employment_type\">\n          <option value=\"regular\" {{selected employee.employment_type \"regular\"}}>Regular</option>\n          <option value=\"probationary\" {{selected employee.employment_type \"probationary\"}}>Probationary</option>\n          <option value=\"contractual\" {{selected employee.employment_type \"contractual\"}}>Contractual</option>\n        </select></label\n      ><label\n        >Daily rate (₱)<input\n          type=\"number\"\n          name=\"daily_rate\"\n          value=\"{{employee.daily_rate}}\"\n          required\n          min=\"0.01\"\n          max=\"100000\"\n          step=\"0.01\" /></label\n      ><label\n        >Hire date<input\n          type=\"date\"\n          name=\"hire_date\"\n          value=\"{{employee.hire_date}}\"\n          required /></label\n      ><label\n        >Status<select name=\"status\">\n          <option value=\"active\" {{selected employee.status \"active\"}}>Active</option>\n          <option value=\"inactive\" {{selected employee.status \"inactive\"}}>Inactive</option>\n          <option value=\"resigned\" {{selected employee.status \"resigned\"}}>Resigned</option>\n        </select></label\n      >\n    </div>\n    <div class=\"form-actions\">\n      <a class=\"btn\" href=\"/employees\">Cancel</a\n      ><button class=\"btn primary\">Save employee</button>\n    </div>\n  </form>\n","head":"<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"/images/mindafresh-logo.svg\">\n  <title>{{title}} | MindaFresh PeoplePay</title>\n  <link rel=\"stylesheet\" href=\"/css/utilities.css\">\n  <link rel=\"stylesheet\" href=\"/css/app.css\">\n</head>\n","headerBar":"<header class=\"topbar\">\n  <div class=\"header-row\">\n    <div class=\"header-title\">\n      <button type=\"button\" class=\"sidebar-toggle\" data-sidebar-toggle aria-label=\"Open navigation\" aria-controls=\"sidebar\" aria-expanded=\"false\">\n        <svg viewBox=\"0 0 24 24\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" aria-hidden=\"true\"><path d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n      </button>\n      <span class=\"header-suite\">MindaFresh ERP</span><span class=\"header-divider\">/</span><strong>{{title}}</strong>\n    </div>\n    <div class=\"account\">\n      <span class=\"account-avatar\">P</span>\n      <div class=\"account-details\"><strong>{{currentUser.username}}</strong><small>{{currentUser.role}}</small></div>\n      <form method=\"post\" action=\"/logout\">\n        <input type=\"hidden\" name=\"_csrf\" value=\"{{csrf}}\">\n        <button class=\"btn small\" type=\"submit\">Logout</button>\n      </form>\n    </div>\n  </div>\n</header>\n","messages":"{{#each success_msg}}\n<div class=\"flash success\" role=\"status\">{{this}}</div>\n{{/each}} {{#each error_msg}}\n<div class=\"flash error\" role=\"alert\">{{this}}</div>\n{{/each}}\n","modals/leaveDialog":"<dialog id=\"leaveDialog\">\n  <div class=\"dialog-heading\">\n    <h2>Request leave</h2>\n    <button class=\"btn small\" data-close>Close</button>\n  </div>\n  <form method=\"post\" action=\"/leaves\" class=\"form-content\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{csrf}}\" /><input\n      type=\"hidden\"\n      name=\"return_to\"\n      value=\"/leaves\"\n    />\n    <div class=\"form-grid\">\n      <label\n        >Employee<select name=\"employee_id\" required>\n          {{#each employees}}{{#if (eq status \"active\")}}\n          <option value=\"{{id}}\">{{full_name}}</option>\n          {{/if}}{{/each}}\n        </select></label\n      ><label\n        >Leave type<select name=\"leave_type\">\n          <option value=\"vacation\">Vacation</option>\n          <option value=\"sick\">Sick</option>\n          <option value=\"emergency\">Emergency</option>\n          <option value=\"unpaid\">Unpaid</option>\n        </select></label\n      ><label>Start date<input type=\"date\" name=\"start_date\" required /></label\n      ><label>End date<input type=\"date\" name=\"end_date\" required /></label\n      ><label class=\"full\"\n        >Reason<textarea\n          name=\"reason\"\n          maxlength=\"255\"\n          rows=\"3\"\n          required\n        ></textarea>\n      </label>\n    </div>\n    <div class=\"form-actions\">\n      <button type=\"button\" class=\"btn\" data-close>Cancel</button\n      ><button class=\"btn primary\">Submit request</button>\n    </div>\n  </form>\n</dialog>\n","modals/payrollDialog":"<dialog id=\"payrollDialog\">\n  <div class=\"dialog-heading\">\n    <h2>Prepare payroll</h2>\n    <button class=\"btn small\" data-close>Close</button>\n  </div>\n  <form method=\"post\" action=\"/payroll\" class=\"form-content\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{csrf}}\" /><input\n      type=\"hidden\"\n      name=\"return_to\"\n      value=\"/payroll\"\n    />\n    <p class=\"muted\">\n      Choose a completed half-month: 1–15 or 16–month end. Actual attendance is\n      read from the shared database.\n    </p>\n    <div class=\"form-grid\">\n      <label\n        >Period start<input name=\"period_start\" type=\"date\" required /></label\n      ><label>Period end<input name=\"period_end\" type=\"date\" required /></label>\n    </div>\n    <div class=\"form-actions\">\n      <button type=\"button\" class=\"btn\" data-close>Cancel</button\n      ><button class=\"btn primary\">Calculate draft</button>\n    </div>\n  </form>\n</dialog>\n","pages/attendance":"<div class=\"page-heading\"><div><h1>Attendance</h1><p>Read-only daily time records from the shared Attendance module.</p></div><a class=\"btn\" href=\"/attendance\">Today’s month</a></div>\n<div class=\"note\">Timekeeping, kiosk punches and corrections belong to Attendance. Lunch punches are recorded; the fixed one-hour lunch deduction remains unchanged.</div>\n{{> forms/attendanceFilter}}\n<section class=\"panel\"><div class=\"panel-heading\"><h2>Daily time records</h2><span class=\"muted\">{{date start}} – {{date end}} · {{attendance.length}} records</span></div>\n<div class=\"table-wrap\"><table><thead><tr><th>Employee</th><th>Date</th><th>Time in</th><th>Lunch out</th><th>Lunch in</th><th>Time out</th><th>Hours</th><th>Late min.</th><th>Undertime min.</th><th>Status</th></tr></thead><tbody>\n{{#each attendance}}<tr><td>{{employee_name}}</td><td>{{date log_date}}</td><td>{{time_in_display}}</td><td>{{lunch_out_display}}</td><td>{{lunch_in_display}}</td><td>{{time_out_display}}</td><td>{{hours_worked}}</td><td>{{late_minutes}}</td><td>{{undertime_minutes}}</td><td><span class=\"badge\">{{status}}</span></td></tr>\n{{else}}<tr><td colspan=\"10\" class=\"empty\">No records for these dates. Confirm Attendance writes to the same mindafresh_db, then check the date range and employee.</td></tr>{{/each}}</tbody></table></div>\n<div class=\"signature-lines\"><span>Prepared by</span><span>Approved by</span></div></section>\n","pages/connections":"<div class=\"page-heading\">\n  <div>\n    <h1>ERP connections</h1>\n    <p>Five modules use one database: mindafresh_db.</p>\n  </div>\n</div>\n<section class=\"panel\">\n  <div class=\"panel-heading\">\n    <h2>PeoplePay · HR <span class=\"badge\">Owner</span></h2>\n    <span class=\"muted\">Port 3004</span>\n  </div>\n  <p class=\"panel-copy\">\n    Writes departments, employees, users, leave_requests, payroll_runs and\n    payroll_items. All modules refer to the same employees.id.\n  </p>\n</section>\n<section class=\"panel\">\n  <div class=\"panel-heading\">\n    <h2>Attendance <span class=\"badge green\">Read only</span></h2>\n    <span class=\"muted\">Port 3003</span>\n  </div>\n  <p class=\"panel-copy\">\n    PeoplePay reads attendance_logs and holidays to compute payroll. The\n    Attendance module owns timekeeping and corrections.\n  </p>\n</section>\n<section class=\"panel\">\n  <div class=\"panel-heading\">\n    <h2>Accounting & Finance <span class=\"badge green\">Read only</span></h2>\n    <span class=\"muted\">Port 3005</span>\n  </div>\n  <p class=\"panel-copy\">\n    Accounting reads approved payroll, posts journal_entries and writes\n    salary_releases. PeoplePay shows posted and paid status from those records.\n  </p>\n</section>\n<section class=\"panel\">\n  <div class=\"panel-heading\">\n    <h2>Point of Sale and Online Shop</h2>\n    <span class=\"muted\">Ports 3002 and 3001</span>\n  </div>\n  <p class=\"panel-copy\">\n    Staff use the shared users and employees tables through authService. Shop\n    customer accounts remain separate. No employee data is copied between\n    modules.\n  </p>\n</section>\n<div class=\"note\">\n  These are database integration contracts, not a live health check of the other\n  module servers.\n</div>\n","pages/dashboard":"<div class=\"page-heading\">\n  <div>\n    <h1>Dashboard</h1>\n    <p>Employee records, leave requests and payroll in one workspace.</p>\n  </div>\n  {{#if canManageHR}}<a class=\"btn primary\" href=\"/employees/create\"\n    >Add employee</a\n  >{{/if}}\n</div>\n<div class=\"summary-grid\">\n  <article class=\"summary\">\n    <span>Employees</span><strong>{{employees.length}}</strong\n    ><small>{{activeCount}} active employees</small>\n  </article>\n  <article class=\"summary\">\n    <span>Pending leave requests</span><strong>{{pendingLeaves.length}}</strong\n    ><small>Awaiting HR review</small>\n  </article>\n  <article class=\"summary\">\n    <span>Payroll runs</span><strong>{{runs.length}}</strong\n    ><small>Visible to your role</small>\n  </article>\n  <article class=\"summary\">\n    <span>Latest net payroll</span><strong>{{money latestRun.total_net}}</strong\n    ><small\n      >{{#if latestRun}}{{latestRun.payroll_code}} ·\n      {{latestRun.display_status}}{{else}}No payroll prepared yet{{/if}}</small\n    >\n  </article>\n</div>\n<section class=\"panel\">\n  <div class=\"panel-heading\">\n    <h2>\n      Pending leave requests <span class=\"badge\">{{pendingLeaves.length}}</span>\n    </h2>\n    {{#unless (eq currentUser.role \"accountant\")}}<a\n      class=\"text-link\"\n      href=\"/leaves\"\n      >View leave requests</a\n    >{{/unless}}\n  </div>\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr>\n          <th>Reference</th>\n          <th>Employee</th>\n          <th>Type</th>\n          <th>Period</th>\n          <th>Days</th>\n        </tr>\n      </thead>\n      <tbody>\n        {{#each pendingLeaves}}\n        <tr>\n          <td>{{leave_code}}</td>\n          <td>{{employee_name}}</td>\n          <td>{{leave_type}}</td>\n          <td>{{date start_date}} – {{date end_date}}</td>\n          <td>{{days}}</td>\n        </tr>\n        {{else}}\n        <tr>\n          <td colspan=\"5\" class=\"empty\">No pending leave requests.</td>\n        </tr>\n        {{/each}}\n      </tbody>\n    </table>\n  </div>\n</section>\n<section class=\"panel\">\n  <div class=\"panel-heading\">\n    <h2>Payroll runs <span class=\"badge green\">{{runs.length}}</span></h2>\n    {{#if canReadPayroll}}<a class=\"text-link\" href=\"/payroll\">View payroll</a\n    >{{else}}<a class=\"text-link\" href=\"/payslips\">View my payslips</a>{{/if}}\n  </div>\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr>\n          <th>Reference</th>\n          <th>Period</th>\n          <th>Employees</th>\n          <th>Status</th>\n          <th class=\"amount\">Net amount</th>\n        </tr>\n      </thead>\n      <tbody>\n        {{#each runs}}\n        <tr>\n          <td>{{payroll_code}}</td>\n          <td>{{date period_start}} – {{date period_end}}</td>\n          <td>{{employee_count}}</td>\n          <td><span class=\"badge\">{{display_status}}</span></td>\n          <td class=\"amount\">{{money total_net}}</td>\n        </tr>\n        {{else}}\n        <tr>\n          <td colspan=\"5\" class=\"empty\">No payroll runs available.</td>\n        </tr>\n        {{/each}}\n      </tbody>\n    </table>\n  </div>\n</section>\n<div class=\"note\">\n  Attendance owns time records. Accounting posts approved payroll and releases\n  salaries. PeoplePay reads their shared records.\n</div>\n","pages/departments":"<div class=\"page-heading\">\n  <div>\n    <h1>Departments</h1>\n    <p>Manage the departments used by your employee records.</p>\n  </div>\n</div>\n<section class=\"panel\">\n  <div class=\"panel-heading\"><h2>Add department</h2></div>\n  <form method=\"post\" action=\"/departments\" class=\"inline-form\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{csrf}}\" /><input\n      type=\"hidden\"\n      name=\"return_to\"\n      value=\"/departments\"\n    /><input\n      aria-label=\"Department name\"\n      name=\"name\"\n      placeholder=\"Department name\"\n      required\n      maxlength=\"100\"\n    /><button class=\"btn primary\">Add department</button>\n  </form>\n</section>\n<section class=\"panel\">\n  <div class=\"panel-heading\"><h2>Department directory</h2></div>\n  {{#each departments}}\n  <form\n    class=\"inline-form divided\"\n    method=\"post\"\n    action=\"/departments/{{id}}/update\"\n  >\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{@root.csrf}}\" /><input\n      type=\"hidden\"\n      name=\"return_to\"\n      value=\"/departments\"\n    /><span class=\"code\">{{department_code}}</span\n    ><input\n      aria-label=\"Edit department name\"\n      name=\"name\"\n      value=\"{{name}}\"\n      required\n      maxlength=\"100\"\n    /><button class=\"btn\">Save</button>\n  </form>\n  {{else}}\n  <div class=\"empty\">No departments yet.</div>\n  {{/each}}\n</section>\n","pages/employee-form":"<div class=\"page-heading\">\n  <div>\n    <h1>{{title}}</h1>\n    <p>Changes update the shared employee record.</p>\n  </div>\n  <a href=\"/employees\" class=\"btn\">Back to employees</a>\n</div>\n<section class=\"panel\">\n  {{> forms/employeeForm}}\n</section>\n","pages/employees":"<div class=\"page-heading\">\n  <div>\n    <h1>Employees</h1>\n    <p>One employee master record shared across all MindaFresh modules.</p>\n  </div>\n  <div class=\"actions\">\n    <a href=\"/reports/employees/export\" class=\"btn\">Export CSV</a>{{#if\n    canManageHR}}<a href=\"/employees/create\" class=\"btn primary\">Add employee</a\n    >{{/if}}\n  </div>\n</div>\n<section class=\"panel\">\n  <form class=\"filter-row\" action=\"/employees\" method=\"get\">\n    <input\n      aria-label=\"Search employees\"\n      name=\"search\"\n      value=\"{{search}}\"\n      placeholder=\"Search name, code, position or department\"\n    /><select aria-label=\"Filter by status\" name=\"status\">\n      <option value=\"\">All statuses</option>\n      <option value=\"active\" {{selected status \"active\"}}>Active</option>\n      <option value=\"inactive\" {{selected status \"inactive\"}}>Inactive</option>\n      <option value=\"resigned\" {{selected status \"resigned\"}}>Resigned</option></select\n    ><button class=\"btn\">Search</button\n    ><a class=\"text-link\" href=\"/employees\">Clear</a>\n  </form>\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr>\n          <th>Employee code</th>\n          <th>Name</th>\n          <th>Department</th>\n          <th>Position</th>\n          <th>Employment</th>\n          <th class=\"amount\">Daily rate</th>\n          <th>Status</th>\n          <th></th>\n        </tr>\n      </thead>\n      <tbody>\n        {{#each employees}}\n        <tr>\n          <td>{{employee_code}}</td>\n          <td><strong>{{full_name}}</strong><small>{{email}}</small></td>\n          <td>{{department}}</td>\n          <td>{{position}}</td>\n          <td>{{employment_type}}</td>\n          <td class=\"amount\">{{money daily_rate}}</td>\n          <td><span class=\"badge\">{{status}}</span></td>\n          <td>\n            {{#if @root.canManageHR}}<a\n              class=\"text-link\"\n              href=\"/employees/{{id}}/edit\"\n              >Edit</a\n            >{{/if}}\n          </td>\n        </tr>\n        {{else}}\n        <tr>\n          <td colspan=\"8\" class=\"empty\">No matching employees.</td>\n        </tr>\n        {{/each}}\n      </tbody>\n    </table>\n  </div>\n</section>\n","pages/error":"<main class=\"container\"><section class=\"panel form-content\"><h1>{{title}}</h1><p>{{message}}</p><a class=\"btn primary\" href=\"/dashboard\">Return to dashboard</a></section></main>\n","pages/leaves":"<div class=\"page-heading\">\n  <div>\n    <h1>Leave requests</h1>\n    <p>Vacation, sick, emergency and unpaid leave in whole working days.</p>\n  </div>\n  <button class=\"btn primary\" data-open=\"leaveDialog\">Request leave</button>\n</div>\n<section class=\"panel\">\n  <div class=\"panel-heading\">\n    <h2>Leave balances</h2>\n    <span class=\"muted\">Emergency leave uses the vacation balance.</span>\n  </div>\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr>\n          <th>Employee</th>\n          <th>Vacation days</th>\n          <th>Sick days</th>\n        </tr>\n      </thead>\n      <tbody>\n        {{#each employees}}\n        <tr>\n          <td>{{full_name}}</td>\n          <td>{{vacation_leave_balance}}</td>\n          <td>{{sick_leave_balance}}</td>\n        </tr>\n        {{/each}}\n      </tbody>\n    </table>\n  </div>\n</section>\n<section class=\"panel\">\n  <div class=\"panel-heading\">\n    <h2>Requests <span class=\"badge\">{{leaves.length}}</span></h2>\n  </div>\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr>\n          <th>Reference</th>\n          <th>Employee</th>\n          <th>Leave / reason</th>\n          <th>Dates</th>\n          <th>Days</th>\n          <th>Status</th>\n          <th>Action</th>\n        </tr>\n      </thead>\n      <tbody>\n        {{#each leaves}}\n        <tr>\n          <td>{{leave_code}}</td>\n          <td>{{employee_name}}</td>\n          <td>{{leave_type}}<small>{{reason}}</small></td>\n          <td>{{date start_date}} – {{date end_date}}</td>\n          <td>{{days}}</td>\n          <td><span class=\"badge\">{{status}}</span></td>\n          <td>\n            {{#if can_review}}\n            <form method=\"post\" action=\"/leaves/{{id}}/update\" class=\"actions\">\n              <input type=\"hidden\" name=\"_csrf\" value=\"{{@root.csrf}}\" /><input\n                type=\"hidden\"\n                name=\"return_to\"\n                value=\"/leaves\"\n              /><button\n                class=\"btn small primary\"\n                name=\"status\"\n                value=\"approved\"\n              >\n                Approve</button\n              ><button class=\"btn small\" name=\"status\" value=\"rejected\">\n                Reject\n              </button>\n            </form>\n            {{/if}}{{#if can_cancel}}\n            <form method=\"post\" action=\"/leaves/{{id}}/update\">\n              <input type=\"hidden\" name=\"_csrf\" value=\"{{@root.csrf}}\" /><input\n                type=\"hidden\"\n                name=\"return_to\"\n                value=\"/leaves\"\n              /><button class=\"btn small\" name=\"status\" value=\"cancelled\">\n                Cancel\n              </button>\n            </form>\n            {{/if}}\n          </td>\n        </tr>\n        {{else}}\n        <tr>\n          <td colspan=\"7\" class=\"empty\">No leave requests.</td>\n        </tr>\n        {{/each}}\n      </tbody>\n    </table>\n  </div>\n</section>\n{{> modals/leaveDialog}}\n","pages/login":"<main class=\"login-container\"><section class=\"panel login-panel\"><a class=\"brand\" href=\"/login\"><img class=\"brand-logo\" src=\"/images/mindafresh-logo.svg\" alt=\"MindaFresh logo\"><strong>MindaFresh <span>PeoplePay</span></strong></a><h1>Sign in</h1><p class=\"muted\">Use your shared MindaFresh staff account.</p>{{> messages}}<form method=\"post\" action=\"/login\"><input type=\"hidden\" name=\"_csrf\" value=\"{{csrf}}\"><input type=\"hidden\" name=\"return_to\" value=\"/login\"><label>Username<input name=\"username\" autocomplete=\"username\" required maxlength=\"50\"></label><label>Password<input type=\"password\" name=\"password\" autocomplete=\"current-password\" required maxlength=\"72\"></label><button class=\"btn primary full-button\">Sign in</button></form><p class=\"muted\">Need an account? Contact your administrator.</p></section></main>\n","pages/payroll-detail":"<div class=\"page-heading\">\n  <div>\n    <h1>{{run.payroll_code}}</h1>\n    <p>\n      {{date run.period_start}} – {{date run.period_end}} ·\n      {{run.employee_count}} employees · {{run.display_status}}\n    </p>\n  </div>\n  <a class=\"btn\" href=\"/payroll\">Back to payroll</a>\n</div>\n{{#if run.is_draft}}\n<div class=\"note\">\n  Review all payslips. Recompute the draft if attendance, leave or employee\n  rates changed. Approval locks this run.\n</div>\n{{else}}\n<div class=\"note\">\n  This payroll is approved and locked. Accounting owns journal posting and\n  salary release.\n</div>\n{{/if}}\n<section class=\"panel\">\n  <div class=\"panel-heading\"><h2>Employee calculations</h2></div>\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr>\n          <th>Employee</th>\n          <th>Worked</th>\n          <th>Paid leave</th>\n          <th>Holiday</th>\n          <th>Late / undertime</th>\n          <th class=\"amount\">Gross</th>\n          <th class=\"amount\">Net</th>\n          <th></th>\n        </tr>\n      </thead>\n      <tbody>\n        {{#each run.items}}\n        <tr>\n          <td>{{employee_name}}</td>\n          <td>{{days_worked}} days</td>\n          <td>{{paid_leave_days}}</td>\n          <td>{{paid_holiday_days}}</td>\n          <td>{{late_minutes}} / {{undertime_minutes}} min</td>\n          <td class=\"amount\">{{money gross_pay}}</td>\n          <td class=\"amount\">{{money net_pay}}</td>\n          <td>\n            <a\n              href=\"/payslips/{{@root.run.id}}/{{employee_id}}\"\n              class=\"text-link\"\n              >Payslip</a\n            >\n          </td>\n        </tr>\n        {{/each}}\n      </tbody>\n    </table>\n  </div>\n  <div class=\"panel-total\">\n    <strong>Total net payroll</strong><strong>{{money run.total_net}}</strong>\n  </div>\n</section>\n{{#if run.is_draft}}\n<div class=\"actions right\">\n  {{#if canManageHR}}\n  <form method=\"post\" action=\"/payroll/{{run.id}}/recompute\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{csrf}}\" /><input\n      type=\"hidden\"\n      name=\"return_to\"\n      value=\"/payroll\"\n    /><button class=\"btn\">Recompute draft</button>\n  </form>\n  {{/if}}{{#if isAdmin}}\n  <form\n    method=\"post\"\n    action=\"/payroll/{{run.id}}/approve\"\n    data-confirm=\"Approve and lock this payroll? Review every payslip first.\"\n  >\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{csrf}}\" /><input\n      type=\"hidden\"\n      name=\"return_to\"\n      value=\"/payroll\"\n    /><button class=\"btn primary\">Approve payroll</button>\n  </form>\n  {{/if}}\n</div>\n{{/if}}\n","pages/payroll":"<div class=\"page-heading\">\n  <div>\n    <h1>Payroll</h1>\n    <p>Prepare, review and approve payroll before Accounting posts it.</p>\n  </div>\n  {{#if canManageHR}}<button class=\"btn primary\" data-open=\"payrollDialog\">\n    Prepare payroll</button\n  >{{/if}}\n</div>\n<div class=\"note\">\n  Academic rates only. Employer shares are excluded. Review config/payroll.js\n  before operational use.\n</div>\n<section class=\"panel\">\n  <div class=\"panel-heading\">\n    <h2>Payroll runs <span class=\"badge\">{{runs.length}}</span></h2>\n    <span class=\"muted\">Draft → Approved → Posted → Paid</span>\n  </div>\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr>\n          <th>Reference</th>\n          <th>Period</th>\n          <th>Employees</th>\n          <th class=\"amount\">Gross</th>\n          <th class=\"amount\">Deductions</th>\n          <th class=\"amount\">Net amount</th>\n          <th>Status</th>\n          <th></th>\n        </tr>\n      </thead>\n      <tbody>\n        {{#each runs}}\n        <tr>\n          <td>{{payroll_code}}</td>\n          <td>{{date period_start}} – {{date period_end}}</td>\n          <td>{{employee_count}}</td>\n          <td class=\"amount\">{{money total_gross}}</td>\n          <td class=\"amount\">{{money total_deductions}}</td>\n          <td class=\"amount\">{{money total_net}}</td>\n          <td><span class=\"badge\">{{display_status}}</span></td>\n          <td><a class=\"text-link\" href=\"/payroll/{{id}}\">Review</a></td>\n        </tr>\n        {{else}}\n        <tr>\n          <td colspan=\"8\" class=\"empty\">No payroll runs yet.</td>\n        </tr>\n        {{/each}}\n      </tbody>\n    </table>\n  </div>\n</section>\n{{#if canManageHR}}\n{{> modals/payrollDialog}}\n{{/if}}\n","pages/payslip":"<div class=\"page-heading\">\n  <div>\n    <h1>Employee payslip</h1>\n    <p>\n      {{run.payroll_code}} · {{date run.period_start}} – {{date run.period_end}}\n    </p>\n  </div>\n  <div class=\"actions\">\n    <a class=\"btn\" href=\"/payslips\">Back</a\n    ><button class=\"btn primary\" data-print>Print / Save PDF</button>\n  </div>\n</div>\n<section class=\"panel payslip\">\n  <div class=\"panel-heading\">\n    <div>\n      <h2>MindaFresh Food Distribution, Inc.</h2>\n      <p class=\"muted\">PeoplePay · HR and Payroll</p>\n    </div>\n    <span class=\"badge\">{{run.display_status}}</span>\n  </div>\n  <div class=\"payslip-person\">\n    <strong>{{employee.full_name}}</strong>\n    <p>\n      {{employee.employee_code}} · {{employee.position}} ·\n      {{employee.department}}\n    </p>\n  </div>\n  <table>\n    <tbody>\n      <tr>\n        <td>Daily rate</td>\n        <td class=\"amount\">{{money item.daily_rate}}</td>\n      </tr>\n      <tr>\n        <td>Basic pay</td>\n        <td class=\"amount\">{{money item.basic_pay}}</td>\n      </tr>\n      <tr>\n        <td>Tardiness / undertime deduction</td>\n        <td class=\"amount\">{{money item.tardiness_deduction}}</td>\n      </tr>\n      <tr>\n        <td><strong>Gross pay</strong></td>\n        <td class=\"amount\"><strong>{{money item.gross_pay}}</strong></td>\n      </tr>\n      <tr>\n        <td>SSS</td>\n        <td class=\"amount\">{{money item.sss}}</td>\n      </tr>\n      <tr>\n        <td>PhilHealth</td>\n        <td class=\"amount\">{{money item.philhealth}}</td>\n      </tr>\n      <tr>\n        <td>Pag-IBIG</td>\n        <td class=\"amount\">{{money item.pagibig}}</td>\n      </tr>\n      <tr>\n        <td>Withholding tax</td>\n        <td class=\"amount\">{{money item.withholding_tax}}</td>\n      </tr>\n    </tbody>\n  </table>\n  <div class=\"panel-total\">\n    <strong>Net pay</strong><strong>{{money item.net_pay}}</strong>\n  </div>\n  <p class=\"muted payslip-person\">\n    Worked: {{item.days_worked}} days · Paid leave: {{item.paid_leave_days}}\n    days · Regular holidays: {{item.paid_holiday_days}} days\n  </p>\n</section>\n<div class=\"note\">\n  Academic calculation using simplified rates; employer shares excluded.\n</div>\n","pages/payslips":"<div class=\"page-heading\">\n  <div>\n    <h1>Payslips</h1>\n    <p>\n      {{#if isEmployee}}Your payslips appear after Accounting releases your\n      salary.{{else}}Review employee payslips by payroll period.{{/if}}\n    </p>\n  </div>\n</div>\n<section class=\"panel\">\n  <div class=\"panel-heading\"><h2>Employee payslips</h2></div>\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr>\n          <th>Payroll</th>\n          <th>Employee</th>\n          <th>Period</th>\n          <th class=\"amount\">Gross</th>\n          <th class=\"amount\">Net</th>\n          <th>Status</th>\n          <th></th>\n        </tr>\n      </thead>\n      <tbody>\n        {{#each runs}}{{#each items}}\n        <tr>\n          <td>{{../payroll_code}}</td>\n          <td>{{employee_name}}</td>\n          <td>{{date ../period_start}} – {{date ../period_end}}</td>\n          <td class=\"amount\">{{money gross_pay}}</td>\n          <td class=\"amount\">{{money net_pay}}</td>\n          <td><span class=\"badge\">{{../display_status}}</span></td>\n          <td>\n            <a class=\"text-link\" href=\"/payslips/{{../id}}/{{employee_id}}\"\n              >View</a\n            >\n          </td>\n        </tr>\n        {{/each}}{{else}}\n        <tr>\n          <td colspan=\"7\" class=\"empty\">No payslips available.</td>\n        </tr>\n        {{/each}}\n      </tbody>\n    </table>\n  </div>\n</section>\n","pages/profile":"<div class=\"page-heading\"><div><h1>My profile</h1><p>Your shared MindaFresh employee record. Contact HR for corrections.</p></div></div>\n<section class=\"panel\"><dl class=\"profile-grid\">\n<div><dt>Employee code</dt><dd>{{employee.employee_code}}</dd></div><div><dt>Name</dt><dd>{{employee.first_name}} {{employee.middle_name}} {{employee.last_name}}</dd></div>\n<div><dt>Department</dt><dd>{{employee.department}}</dd></div><div><dt>Position</dt><dd>{{employee.position}}</dd></div><div><dt>Hire date</dt><dd>{{date employee.hire_date}}</dd></div><div><dt>Status</dt><dd>{{employee.status}}</dd></div>\n<div><dt>Vacation balance</dt><dd>{{employee.vacation_leave_balance}} days</dd></div><div><dt>Sick balance</dt><dd>{{employee.sick_leave_balance}} days</dd></div></dl></section>\n","pages/reports":"<div class=\"page-heading\">\n  <div>\n    <h1>Reports</h1>\n    <p>Workforce and payroll records for review and export.</p>\n  </div>\n  <button class=\"btn\" data-print>Print report</button>\n</div>\n<div class=\"summary-grid\">\n  <article class=\"summary\">\n    <span>Employees</span><strong>{{employees.length}}</strong>\n  </article>\n  <article class=\"summary\">\n    <span>Active</span><strong>{{activeCount}}</strong>\n  </article>\n  <article class=\"summary\">\n    <span>Gross payroll</span><strong>{{money totalGross}}</strong>\n  </article>\n  <article class=\"summary\">\n    <span>Net payroll</span><strong>{{money totalNet}}</strong>\n  </article>\n</div>\n<section class=\"panel\">\n  <div class=\"panel-heading\"><h2>Headcount by department</h2></div>\n  <table>\n    <thead>\n      <tr>\n        <th>Department</th>\n        <th class=\"amount\">Employees</th>\n      </tr>\n    </thead>\n    <tbody>\n      {{#each departments}}\n      <tr>\n        <td>{{name}}</td>\n        <td class=\"amount\">{{headcount}}</td>\n      </tr>\n      {{/each}}\n    </tbody>\n  </table>\n</section>\n<section class=\"panel\">\n  <div class=\"panel-heading\"><h2>CSV exports</h2></div>\n  <div class=\"form-content actions\">\n    <a class=\"btn\" href=\"/reports/employees/export\">Employee directory</a>{{#if\n    canManageHR}}<a class=\"btn\" href=\"/reports/leaves/export\">Leave register</a\n    >{{/if}}<a class=\"btn primary\" href=\"/reports/payroll/export\"\n      >Payroll register</a\n    >\n  </div>\n</section>\n","pages/settings":"<div class=\"page-heading\">\n  <div>\n    <h1>Settings</h1>\n    <p>PeoplePay account and environment information.</p>\n  </div>\n</div>\n<section class=\"panel\">\n  <div class=\"panel-heading\"><h2>Signed-in account</h2></div>\n  <table>\n    <tbody>\n      <tr>\n        <td>Username</td>\n        <td>{{currentUser.username}}</td>\n      </tr>\n      <tr>\n        <td>Role</td>\n        <td>{{currentUser.role}}</td>\n      </tr>\n      <tr>\n        <td>Shared employee ID</td>\n        <td>{{currentUser.employee_id}}</td>\n      </tr>\n    </tbody>\n  </table>\n</section>\n{{#if canManageHR}}\n<section class=\"panel\">\n  <div class=\"panel-heading\"><h2>Administration</h2></div>\n  <div class=\"form-content actions\">\n    <a class=\"btn\" href=\"/departments\">Manage departments</a\n    ><a class=\"btn primary\" href=\"/users\">Manage staff accounts</a>\n  </div>\n</section>\n{{/if}}\n<section class=\"panel\">\n  <div class=\"panel-heading\"><h2>System configuration</h2></div>\n  <table>\n    <tbody>\n      <tr>\n        <td>Database</td>\n        <td>mindafresh_db · shared ERP database</td>\n      </tr>\n      <tr>\n        <td>Framework</td>\n        <td>XianFire · Express · hbs</td>\n      </tr>\n      <tr>\n        <td>Views</td>\n        <td>.xian / Handlebars</td>\n      </tr>\n      <tr>\n        <td>Session storage</td>\n        <td>Memory · local development</td>\n      </tr>\n      <tr>\n        <td>Payroll configuration</td>\n        <td>config/payroll.js · academic rates</td>\n      </tr>\n    </tbody>\n  </table>\n</section>","pages/users":"<div class=\"page-heading\">\n  <div>\n    <h1>Staff accounts</h1>\n    <p>One login per employee, shared by the ERP modules.</p>\n  </div>\n</div>\n<section class=\"panel\">\n  <div class=\"panel-heading\">\n    <h2>Create account</h2>\n    <span class=\"muted\">Add the employee first.</span>\n  </div>\n  <form method=\"post\" action=\"/users\" class=\"form-content\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{csrf}}\" /><input\n      type=\"hidden\"\n      name=\"return_to\"\n      value=\"/users\"\n    />\n    <div class=\"form-grid\">\n      <label\n        >Employee<select name=\"employee_id\" required>\n          <option value=\"\">Choose an employee</option>\n          {{#each availableEmployees}}\n          <option value=\"{{id}}\">{{employee_code}} · {{full_name}}</option>\n          {{/each}}\n        </select></label\n      ><label\n        >Username<input\n          name=\"username\"\n          required\n          minlength=\"3\"\n          maxlength=\"50\"\n          pattern=\"[A-Za-z0-9_.-]+\"\n          autocomplete=\"off\" /></label\n      ><label\n        >Role<select name=\"role\">\n          {{#each roles}}\n          <option value=\"{{this}}\">{{this}}</option>\n          {{/each}}\n        </select></label\n      ><label\n        >Password<input\n          type=\"password\"\n          name=\"password\"\n          required\n          minlength=\"10\"\n          maxlength=\"72\"\n          autocomplete=\"new-password\"\n      /></label>\n    </div>\n    <div class=\"form-actions\">\n      <button class=\"btn primary\">Create account</button>\n    </div>\n  </form>\n</section>\n<section class=\"panel\">\n  <div class=\"panel-heading\"><h2>Existing accounts</h2></div>\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr>\n          <th>Username</th>\n          <th>Employee</th>\n          <th>Role / status</th>\n        </tr>\n      </thead>\n      <tbody>\n        {{#each users}}\n        <tr>\n          <td>{{username}}</td>\n          <td>{{employee_name}}</td>\n          <td>\n            {{#if can_manage}}\n            <form\n              method=\"post\"\n              action=\"/users/{{id}}/update\"\n              class=\"inline-form compact\"\n            >\n              <input type=\"hidden\" name=\"_csrf\" value=\"{{@root.csrf}}\" /><input\n                type=\"hidden\"\n                name=\"return_to\"\n                value=\"/users\"\n              /><select name=\"role\" aria-label=\"Account role\">\n                {{#each @root.roles}}\n                <option value=\"{{this}}\" {{selected this ../role}}>{{this}}</option>\n                {{/each}}</select\n              ><select name=\"status\" aria-label=\"Account status\">\n                <option value=\"active\" {{selected status \"active\"}}>Active</option>\n                <option value=\"disabled\" {{selected status \"disabled\"}}>\n                  Disabled\n                </option></select\n              ><button class=\"btn small\">Save</button>\n            </form>\n            {{else}}{{role}} · {{status}}{{/if}}\n          </td>\n        </tr>\n        {{else}}\n        <tr>\n          <td colspan=\"3\" class=\"empty\">No staff accounts.</td>\n        </tr>\n        {{/each}}\n      </tbody>\n    </table>\n  </div>\n</section>\n","scripts":"<script src=\"/js/dialogs.js\" defer></script>\n<script src=\"/js/sidebar.js\" type=\"module\"></script>\n","sidebar":"<a class=\"skip-link\" href=\"#main-content\">Skip to content</a>\n<aside class=\"sidebar\" id=\"sidebar\" aria-label=\"PeoplePay workspace\">\n  <div class=\"sidebar-brand\"><a href=\"/dashboard\" class=\"brand\"><img class=\"brand-logo\" src=\"/images/mindafresh-logo.svg\" alt=\"MindaFresh logo\"><strong>MindaFresh<span>PeoplePay</span></strong></a><button class=\"sidebar-close\" type=\"button\" data-sidebar-close aria-label=\"Close navigation\">×</button></div>\n  <div class=\"sidebar-caption\">HUMAN RESOURCES & PAYROLL</div>\n  <nav aria-label=\"Main navigation\">\n    <p class=\"sidebar-label\">WORKSPACE</p>\n<a href=\"/profile\" class=\"sidebar-link {{#if activeProfile}}active{{/if}}\"><span>My profile</span></a>\n<a href=\"/dashboard\" class=\"sidebar-link {{#if activeDashboard}}active{{/if}}\" {{#if activeDashboard}}aria-current=\"page\"{{/if}}>\n  <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z\"/></svg><span>Dashboard</span>\n</a>\n{{#unless isEmployee}}<a href=\"/employees\" class=\"sidebar-link {{#if activeEmployees}}active{{/if}}\" {{#if activeEmployees}}aria-current=\"page\"{{/if}}>\n  <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0\"/></svg><span>Employees</span>\n</a>{{/unless}}\n{{#if canManageHR}}<a href=\"/attendance\" class=\"sidebar-link {{#if activeAttendance}}active{{/if}}\" {{#if activeAttendance}}aria-current=\"page\"{{/if}}>\n  <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2 M7 14h3 M14 14h3\"/></svg><span>Attendance</span>\n</a>{{/if}}\n{{#unless (eq currentUser.role \"accountant\")}}<a href=\"/leaves\" class=\"sidebar-link {{#if activeLeaves}}active{{/if}}\" {{#if activeLeaves}}aria-current=\"page\"{{/if}}>\n  <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 8v4l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0\"/></svg><span>Leave requests</span>\n</a>{{/unless}}\n{{#if canReadPayroll}}<a href=\"/payroll\" class=\"sidebar-link {{#if activePayroll}}active{{/if}}\" {{#if activePayroll}}aria-current=\"page\"{{/if}}>\n  <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M20 8V5H4a2 2 0 0 1 0-4h14 M3 5v16h18V8H3 M16 12h5v5h-5z\"/></svg><span>Payroll</span>\n</a>{{/if}}\n<a href=\"/payslips\" class=\"sidebar-link {{#if activePayslips}}active{{/if}}\" {{#if activePayslips}}aria-current=\"page\"{{/if}}>\n  <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h6\"/></svg><span>Payslips</span>\n</a>\n{{#unless isEmployee}}<a href=\"/reports\" class=\"sidebar-link {{#if activeReports}}active{{/if}}\" {{#if activeReports}}aria-current=\"page\"{{/if}}>\n  <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 3v18h18 M7 14v3 M12 9v8 M17 5v12\"/></svg><span>Reports</span>\n</a>{{/unless}}\n<p class=\"sidebar-label\">ADMINISTRATION</p>\n{{#if canManageHR}}<a href=\"/departments\" class=\"sidebar-link {{#if activeDepartments}}active{{/if}}\" {{#if activeDepartments}}aria-current=\"page\"{{/if}}>\n  <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 21V5l8-3 8 3v16 M8 8h1 M15 8h1 M8 12h1 M15 12h1 M10 21v-5h4v5\"/></svg><span>Departments</span>\n</a><a href=\"/users\" class=\"sidebar-link {{#if activeUsers}}active{{/if}}\" {{#if activeUsers}}aria-current=\"page\"{{/if}}>\n  <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 2l9 4v6c0 6-9 10-9 10S3 18 3 12V6z M8 12l3 3 5-6\"/></svg><span>Staff accounts</span>\n</a>{{/if}}\n{{#unless isEmployee}}<a href=\"/connections\" class=\"sidebar-link {{#if activeConnections}}active{{/if}}\" {{#if activeConnections}}aria-current=\"page\"{{/if}}>\n  <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M10 13a5 5 0 0 0 7 .5l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7-.5l-3 3a5 5 0 0 0 7 7l2-2\"/></svg><span>ERP connections</span>\n</a>{{/unless}}\n<a href=\"/settings\" class=\"sidebar-link {{#if activeSettings}}active{{/if}}\" {{#if activeSettings}}aria-current=\"page\"{{/if}}>\n  <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2\"/></svg><span>Settings</span>\n</a>\n  </nav>\n  <div class=\"sidebar-bottom\"><span class=\"status-dot\"></span>Part of MindaFresh ERP<small>One database. One connected team.</small></div>\n</aside>\n"};
